            function applyFilters(arrayObj, filterObj) {
                if (!arrayObj) return [];
                return arrayObj.filter(item => {
                    return Object.keys(filterObj).every(key => {
                        let filterValue = String(filterObj[key]).trim();
                        if (filterValue === "" || filterValue === "null" || filterValue === "undefined") return true;

                        const itemValue = item[key];
                        if (itemValue == null) return false;

                        const itemStr = String(itemValue).trim();
                        const filterParts = filterValue.split(',').map(v => v.trim());
                        const itemParts = itemStr.split(/[/,]/).map(v => v.trim());

                        return filterParts.some(fv => itemParts.includes(fv));
                    });
                });
            }

